void sh_css_metrics_start_binary ( struct sh_css_binary_metrics * metrics ) { if ( ! pc_histogram_enabled ) { return ; } isp_histogram = & metrics -> isp_histogram ; sp_histogram = & metrics -> sp_histogram ; make_histogram ( isp_histogram , ISP_PMEM_DEPTH ) ; make_histogram ( sp_histogram , SP_PMEM_DEPTH ) ; insert_binary_metrics ( & sh_css_metrics . binary_metrics , metrics ) ; } 